"""PDF150 printed294–295: lipid hydrolysis and saponification, addition, oxidation, rancidification, types of rancidity, STS insulin."""
from class12_chemistry_opening import pair,section,SOURCE
from class12_chemistry_sync import save
from class12_chemistry_rings import Fig
F=Fig('arrow150');t=F.t;line=F.line
paras=[];layout=[];blocks=[]
def add(e,u,p,kind='paragraph'):
 layout.append({'type':kind,'indices':[len(paras)]});paras.append(pair(e,u,p))
def lines(rows,kind='list'):
 s0=len(paras)
 for r in rows:paras.append(pair(*r))
 layout.append({'type':kind,'indices':list(range(s0,len(paras)))})
def visual(identity,fn):
 blocks.append({'id':identity,'svg':fn('en'),'svgUrdu':fn('ur'),'svgPashto':fn('ps')});layout.append({'type':'visual','blockId':identity})
N={'triacylglycerol':('ٹرائی ایسائل گلیسرول','ټرای اسایل ګلیسرول'),'glycerol':('گلیسرول','ګلیسرول'),'fatty acid':('فیٹی ایسڈ','غوړ اسید'),'a typical fat':('ایک عام چکنائی','یو عادي غوړ'),
   'sodium':('سوڈیم','سوډیم'),'hydroxide':('ہائیڈروآکسائیڈ','هایدروکساید'),'soap':('صابن','صابون'),'Tristearin':('ٹرائی سٹیرن','ټرای سټیرین'),'Stearic Acid':('سٹیرک ایسڈ','سټیریک اسید'),'Distearin':('ڈائی سٹیرن','ډای سټیرین')}
def lb(lang,v):return v if lang=='en' else N[v][0 if lang=='ur' else 1]
def tri(x,y,r='R',rows=('CH₂','CH','CH₂'),omit=()):
 """Stacked triglyceride; x = centre of carbonyl C."""
 s=''
 for k,c in enumerate(rows):
  yy=y+50*k
  if k in omit:s+=t(x-44,yy,c+'—OH',14);continue
  s+=t(x-40,yy,c+'—O—',14)+t(x,yy,'C',14)+t(x+12+5*len(r),yy,'—'+r,14)+line(x-3,yy-12,x-3,yy-24)+line(x+3,yy-12,x+3,yy-24)+t(x,yy-28,'O',11)
 return s+line(x-60,y+6,x-60,y+34)+line(x-60,y+56,x-60,y+84)
def glycerol(x,y):return t(x,y,'CH₂—OH',14)+line(x-18,y+6,x-18,y+34)+t(x,y+50,'CH—OH',14)+line(x-18,y+56,x-18,y+84)+t(x,y+100,'CH₂—OH',14)
def acyl(x,y,l,r):return t(x-8-6.5*len(l),y,l+'—',14)+t(x,y,'C',14)+t(x+8+6.5*len(r),y,'—'+r,14)+line(x-3,y-12,x-3,y-24)+line(x+3,y-12,x+3,y-24)+t(x,y-28,'O',11)
def hydro(lang):
 s=F.start(170)+tri(150,40)+t(150,160,lb(lang,'triacylglycerol'),12)+t(270,90,'+ 3H₂O',15)+F.arrow(320,410,84,'H⁺')+glycerol(490,40)+t(490,160,lb(lang,'glycerol'),12)+t(570,90,'+ 3',15)+acyl(660,90,'HO','R')+t(660,160,lb(lang,'fatty acid'),12)
 return s+'</svg>'
def sapon(lang):
 s=F.start(175)+tri(150,40)+t(150,160,lb(lang,'a typical fat'),12)+t(280,90,'+ 3NaOH',15)+t(280,160,lb(lang,'sodium'),12)+t(280,174,lb(lang,'hydroxide'),12)+F.arrow(330,410,84)
 s+=t(500,90,'3R—COONa  +',15)+t(480,160,lb(lang,'soap'),12)+glycerol(650,40)+t(650,160,lb(lang,'glycerol'),12)
 return s.replace('viewBox="0 0 850 175"','viewBox="0 0 850 180"')+'</svg>'
def stearin(lang):
 s=F.start(170)+tri(130,40,'C₁₇H₃₅')+t(130,160,lb(lang,'Tristearin'),12)+t(270,90,'+ H₂O',15)+F.arrow(310,390,84)+t(470,90,'C₁₇H₃₅COOH  +',15)+t(470,160,lb(lang,'Stearic Acid')+'  +',12)
 s+=tri(680,40,'C₁₇H₃₅',omit=(0,))+t(680,160,lb(lang,'Distearin'),12)
 return s+'</svg>'

visual('chem12-p150-fat-hydrolysis',hydro)
add('In case of base hydrolysis, the base reacts with free fatty acids and produce salts of fatty acids called soap. This process is called saponification.','اساسی ہائیڈرولائسز کی صورت میں اساس آزاد فیٹی ایسڈز سے تعامل کر کے فیٹی ایسڈز کے نمکیات بناتی ہے جنہیں صابن کہتے ہیں۔ اس عمل کو سیپونیفکیشن کہتے ہیں۔','د قلوي هایدرولایسس په حالت کې قلوي له ازادو غوړ اسیدونو سره تعامل کوي او د غوړ اسیدونو مالګې جوړوي چې صابون بلل کېږي. دې عملیې ته سپونیفیکېشن (صابون جوړونه) وايي.')
visual('chem12-p150-saponification',sapon)
add('Addition reaction','اضافی تعامل','اضافي تعامل','heading')
add('Unsaturated fatty acids of fats and oils undergo addition reactions at the points of unsaturation and produce addition products. The oils, which contain more unsaturation, are hydrogenated to produce solid ghee. By this way inedible and cheap oils such as cotton seed oils are hydrogenated and converted to solid and edible ghee.','چکنائیوں اور تیلوں کے غیر سیر شدہ فیٹی ایسڈز غیر سیر شدگی کے مقامات پر اضافی تعاملات کر کے اضافی پیداوار دیتے ہیں۔ زیادہ غیر سیر شدگی والے تیلوں کو ہائیڈروجنیٹ کر کے ٹھوس گھی بنایا جاتا ہے۔ اس طرح بنولے کے تیل جیسے ناقابلِ خوردنی اور سستے تیلوں کو ہائیڈروجنیٹ کر کے ٹھوس اور خوردنی گھی میں بدلا جاتا ہے۔','د غوړیو او تېلو نامشبوع غوړ اسیدونه د نامشبوعیت په ټکو کې اضافي تعاملونه کوي او اضافي محصولات ورکوي. هغه تېل چې ډېر نامشبوعیت لري هایدروجنېټ کېږي او جامد غوړي جوړوي. په دې توګه د نه خوړلو وړ او ارزانه تېل لکه د پنبې د زړي تېل هایدروجنېټ کېږي او په جامدو او د خوړلو وړ غوړیو بدلېږي.')
add('Oxidation','تکسید','اکسیډېشن','heading')
add('Fats rich in un-saturated fatty acids (e.g linseed oil) undergo spontaneous oxidation at their double bonds and produce aldehydes, ketones and resins. They form a thin transparent coating on the surface to which the oil is applied. These are known as drying oils. They are used in manufacture of paints and varnishes.','غیر سیر شدہ فیٹی ایسڈز سے بھرپور چکنائیاں (مثلاً السی کا تیل) اپنے دوہرے بندوں پر خود بخود تکسید سے الڈیہائیڈز، کیٹونز اور رال بناتی ہیں۔ یہ جس سطح پر تیل لگایا جائے اس پر ایک پتلی شفاف تہہ بناتی ہیں۔ انہیں خشک ہونے والے تیل کہتے ہیں۔ یہ رنگ و روغن اور وارنش کی تیاری میں استعمال ہوتے ہیں۔','هغه غوړي چې له نامشبوع غوړ اسیدونو ډک وي (لکه د زغر تېل) په خپلو دوه ګونو تړونونو کې په خپل سر اکسیډایز کېږي او الدیهایډونه، کیټونونه او رال تولیدوي. د هغې سطحې پر مخ چې تېل پرې لګول کېږي یو نری روڼ پوښ جوړوي. دوی ته وچېدونکي تېل وايي. د رنګونو او وارنیشونو په جوړولو کې کارېږي.')
add('Rancidification','ترشیدگی (رینسڈیفیکیشن)','ترخېدل (رنسیډیفیکېشن)','heading')
add('Natural and specially animal fats contains lipase enzyme. By the action of atmospheric oxygen, in the presence of lipase the fats undergo partial hydrolysis and oxidation at their double bonds. This produces volatile carboxylic acids of sour taste and unpleasant smell. This process is called rancidification and the fat is said to have become rancid.','قدرتی اور خاص طور پر حیوانی چکنائیوں میں لائپیز خامرہ ہوتا ہے۔ فضائی آکسیجن کے عمل سے لائپیز کی موجودگی میں چکنائیوں کی جزوی ہائیڈرولائسز اور ان کے دوہرے بندوں پر تکسید ہوتی ہے۔ اس سے کھٹے ذائقے اور ناگوار بو والے اڑنے والے کاربوکسلک ایسڈز بنتے ہیں۔ اس عمل کو رینسڈیفیکیشن کہتے ہیں اور کہا جاتا ہے کہ چکنائی باسی ہو گئی ہے۔','طبیعي او په ځانګړي ډول حیواني غوړي لایپېز انزایم لري. د هوا د اکسیجن د عمل په واسطه، د لایپېز په شتون کې غوړي جزوي هایدرولایسس او په خپلو دوه ګونو تړونونو کې اکسیډېشن کوي. دا د ترش خوند او ناخوښ بوی لرونکي الوتونکي کاربوکسیلیک اسیدونه تولیدوي. دې عملیې ته رنسیډیفیکېشن وايي او ویل کېږي چې غوړي ترخه شوي.')
visual('chem12-p150-tristearin',stearin)
add('Types of Rancidity','ترشیدگی کی اقسام','د ترخېدو ډولونه','heading')
add('There are three types/pathways of rancidity:','ترشیدگی کی تین اقسام/راستے ہیں:','د ترخېدو درې ډولونه/لارې شته:')
lines([('1. Oxidative Rancidity: Oxidative rancidity also known as autoxidation. The oxidation by the atmospheric O₂ cleave the double bonds of polyunsaturated fatty acids present in triacylglycerols by free radical reactions. This reaction causes the release of malodorous and highly volatile aldehydes and ketones.','1. تکسیدی ترشیدگی: تکسیدی ترشیدگی کو آٹو آکسیڈیشن بھی کہتے ہیں۔ فضائی O₂ سے تکسید آزاد ریڈیکل تعاملات کے ذریعے ٹرائی ایسائل گلیسرولز میں موجود کثیر غیر سیر شدہ فیٹی ایسڈز کے دوہرے بندوں کو توڑ دیتی ہے۔ اس تعامل سے بدبودار اور بہت اڑنے والے الڈیہائیڈز اور کیٹونز خارج ہوتے ہیں۔','1. اکسیډېټیو ترخېدل: اکسیډېټیو ترخېدل د اوټو اکسیډېشن په نوم هم یادېږي. د هوا د O₂ په واسطه اکسیډېشن د ازادو رادیکالونو د تعاملونو له لارې په ټرای اسایل ګلیسرولونو کې د شته څو نامشبوع غوړ اسیدونو دوه ګوني تړونونه ماتوي. دا تعامل د بدبویه او ډېر الوتونکو الدیهایډونو او کیټونونو د خوشې کېدو لامل کېږي.'),
 ('2. Hydrolytic Rancidity: Hydrolytic rancidity also known as hydrolysis/enzymatic oxidation. It is due to the contamination of fat by lipase leading to the release of free fatty acids. In particular, short chain fatty acids, such as butyric acid are malodorous.','2. ہائیڈرولائٹک ترشیدگی: ہائیڈرولائٹک ترشیدگی کو ہائیڈرولائسز/خامری تکسید بھی کہتے ہیں۔ یہ چکنائی میں لائپیز کی آلودگی سے ہوتی ہے جس سے آزاد فیٹی ایسڈز خارج ہوتے ہیں۔ خاص طور پر بیوٹائرک ایسڈ جیسے چھوٹی زنجیر والے فیٹی ایسڈز بدبودار ہوتے ہیں۔','2. هایدرولایټیک ترخېدل: هایدرولایټیک ترخېدل د هایدرولایسس/انزایمي اکسیډېشن په نوم هم یادېږي. دا په غوړیو کې د لایپېز د ککړتیا له امله وي چې د ازادو غوړ اسیدونو د خوشې کېدو لامل کېږي. په ځانګړي ډول لنډ ځنځیر لرونکي غوړ اسیدونه لکه بیوټایریک اسید بدبویه دي.'),
 ('3. Microbial Rancidity: In which micro-organisms such as bacteria, moulds and yeast use their enzymes to break down fats, producing unwanted odours and flavours. Water needs to be present for microbial growth to occur. It can be prevented by sterilization and addition of antioxidant ingredients, such as vitamin E.','3. خردبینی ترشیدگی: اس میں بیکٹیریا، پھپھوندی اور خمیر جیسے خرد جاندار اپنے خامروں سے چکنائیوں کو توڑتے ہیں اور ناپسندیدہ بو اور ذائقے پیدا کرتے ہیں۔ خرد جانداروں کی افزائش کے لیے پانی کا موجود ہونا ضروری ہے۔ اسے جراثیم کشی اور وٹامن E جیسے اینٹی آکسیڈنٹ اجزا شامل کر کے روکا جا سکتا ہے۔','3. مایکروبي ترخېدل: په دې کې مایکرو ژوندي لکه باکتریا، پوڅکي او خمیره خپل انزایمونه د غوړیو د ماتولو لپاره کاروي او ناغوښتي بوی او خوندونه تولیدوي. د مایکروبي ودې لپاره د اوبو شتون اړین دی. د سټرلایز کولو او د ویټامین E په څېر د انټي اکسیډانټ اجزاوو په زیاتولو یې مخنیوی کېدای شي.')],'lines')
add('Society, Technology And Science','معاشرہ، ٹیکنالوجی اور سائنس','ټولنه، ټکنالوژي او ساینس','heading')
add('Insulin is a hormone released from the pancreas (an organ behind the stomach that also produces digestive enzymes). This hormone (insulin) controls the amount of glucose in the blood. Glucose in the bloodstream stimulates the pancreas to produce insulin. Insulin helps glucose to move from the blood into the cells. Inside the cells, glucose is converted to energy, which is used immediately, or the glucose is stored as fat or glycogen in the body until it is needed. The levels of glucose in the blood vary normally throughout the day. They rise after a meal and return to pre-meal levels within about 2 hours after eating. Once the levels of glucose in the blood return to pre-meal levels, insulin production decreases.',
 'انسولین لبلبے (معدے کے پیچھے ایک عضو جو ہضمی خامرے بھی بناتا ہے) سے خارج ہونے والا ہارمون ہے۔ یہ ہارمون (انسولین) خون میں گلوکوز کی مقدار کو کنٹرول کرتا ہے۔ خون میں گلوکوز لبلبے کو انسولین بنانے کی تحریک دیتا ہے۔ انسولین گلوکوز کو خون سے خلیوں میں منتقل ہونے میں مدد دیتی ہے۔ خلیوں کے اندر گلوکوز توانائی میں بدلتا ہے جو فوراً استعمال ہوتی ہے، یا گلوکوز ضرورت تک جسم میں چکنائی یا گلائیکوجن کے طور پر ذخیرہ ہوتا ہے۔ خون میں گلوکوز کی سطح دن بھر معمول کے مطابق بدلتی رہتی ہے۔ یہ کھانے کے بعد بڑھتی ہے اور کھانے کے تقریباً 2 گھنٹوں میں کھانے سے پہلے کی سطح پر واپس آ جاتی ہے۔ جب خون میں گلوکوز کی سطح کھانے سے پہلے کی سطح پر آ جاتی ہے تو انسولین کی پیداوار کم ہو جاتی ہے۔',
 'انسولین له پانقراس (د معدې شاته یو غړی چې هضمي انزایمونه هم تولیدوي) څخه خوشې کېدونکی هورمون دی. دا هورمون (انسولین) په وینه کې د ګلوکوز اندازه کنټرولوي. په وینه کې ګلوکوز پانقراس د انسولین تولید ته هڅوي. انسولین له وینې څخه حجرو ته د ګلوکوز په لېږد کې مرسته کوي. په حجرو کې دننه ګلوکوز په انرژۍ بدلېږي چې سمدستي کارېږي، یا ګلوکوز تر اړتیا پورې په بدن کې د غوړیو یا ګلایکوجن په توګه زېرمه کېږي. په وینه کې د ګلوکوز کچه په عادي ډول د ورځې په اوږدو کې بدلېږي. له خوړو وروسته لوړېږي او له خوړو نږدې 2 ساعته وروسته د خوړو مخکې کچې ته راګرځي. کله چې په وینه کې د ګلوکوز کچه د خوړو مخکې کچې ته راوګرځي، د انسولین تولید کمېږي.')
add('The variation in blood glucose levels is usually within a narrow range, about 70 to 110 mg per 100cm³ of blood in healthy people. If people eat a large amount of carbohydrates, the levels may increase more. If the body does not produce enough insulin to move the glucose into the cells, or if the cells stop responding normally to insulin (called insulin resistance), …','صحت مند لوگوں میں خون میں گلوکوز کی سطح کا تغیر عموماً ایک تنگ حد میں، تقریباً 70 سے 110 mg فی 100cm³ خون ہوتا ہے۔ اگر لوگ کاربوہائیڈریٹس کی بڑی مقدار کھائیں تو سطح مزید بڑھ سکتی ہے۔ اگر جسم گلوکوز کو خلیوں میں منتقل کرنے کے لیے کافی انسولین نہ بنائے، یا خلیے انسولین پر معمول کے مطابق ردِعمل دینا بند کر دیں (جسے انسولین مزاحمت کہتے ہیں)، …','په روغو خلکو کې د وینې د ګلوکوز په کچه کې بدلون معمولاً په یوه تنګه پوله کې، نږدې په هر 100cm³ وینه کې له 70 تر 110 mg پورې وي. که خلک ډېر کاربوهایدرېټونه وخوري، کچه نوره هم لوړېدای شي. که بدن حجرو ته د ګلوکوز د لېږد لپاره کافي انسولین تولید نه کړي، یا حجرې انسولین ته په عادي ډول ځواب ورکول بند کړي (چې د انسولین مقاومت بلل کېږي)، …')
